"""Generate go2rtc's config from cameras.yml.

The generated file keeps ${VAR} references as-is: go2rtc expands
environment variables itself, so no credentials are ever written to disk.
"""

from __future__ import annotations

from pathlib import Path

import yaml

from .config import Config

HEADER = """\
# GENERATED by `docker compose run --rm tools configure` from config/cameras.yml.
# Do not edit by hand; edit cameras.yml and re-run configure.
"""


def build_go2rtc_config(cfg: Config) -> dict:
    streams: dict[str, list[str]] = {}
    for cam in cfg.cameras.values():
        streams[cam.main_stream] = [cam.main]
        if cam.sub_stream:
            streams[cam.sub_stream] = [cam.sub]
    return {
        "api": {"listen": ":1984"},
        "rtsp": {"listen": ":8554"},
        # WebRTC for low-latency live view; candidates get configured when the
        # web app is exposed through the reverse proxy (Phase 4).
        "webrtc": {"listen": ":8555"},
        "log": {"level": "info"},
        "streams": streams,
    }


def write_go2rtc_config(cfg: Config, out_dir: Path) -> Path:
    out_dir.mkdir(parents=True, exist_ok=True)
    path = out_dir / "go2rtc.yaml"
    body = yaml.safe_dump(build_go2rtc_config(cfg), sort_keys=False, default_flow_style=False)
    path.write_text(HEADER + body, encoding="utf-8")
    return path
